        _hole2.addCurve(to: CGPoint(x: 0.616125*width, y: 0.83125*height), control1: CGPoint(x: 0.6182916667*width, y: 0.8126666667*height), control2: CGPoint(x: 0.6115*width, y: 0.8251666667*height))
